//! The IO half — SSH and scp against a real device.
//!
//! Nothing here decides anything; every rule lives in [`crate::plan`], which is pure. This module's
//! only job is to make the facts available and to carry out a sequence whose steps are ordered so that
//! **no step is destructive until the one before it has been verified**.

pub use probe_arch::probe_arch;
pub use read_state::read_state;
pub use swap::swap;
pub use revert::revert;
pub use restart::restart;
pub use probe::probe;

use crate::roster::Device;
use std::process::Command;

/// Where the deploy tree lives on a device. Under `$HOME`, so a deploy needs no root — the binary a
/// service runs is reached through the `current` symlink and root is only ever needed to restart a
/// unit, which is a separate, narrower grant.
pub const REMOTE_ROOT: &str = ".bsc-deploy";

// The three PURE helpers — `parse_state`, `read_probe`, `probe_script` — are each their own leaf
// record now (`each-method-a-single-record`). The IO steps below call them unqualified via these
// re-exports; nothing else in the module changed.
pub use parse_state::parse_state;
pub use read_probe::read_probe;
pub use probe_script::probe_script;

/// Run a command over SSH, returning stdout on success. `BatchMode=yes` so a missing key FAILS rather
/// than blocking forever on a password prompt nobody is there to answer.
pub fn ssh(device: &Device, script: &str) -> Result<String, String> {
    let out = Command::new("ssh")
        .args(["-o", "BatchMode=yes", "-o", "ConnectTimeout=8", &device.ssh, script])
        .output()
        .map_err(|e| format!("cannot run ssh: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "{} — ssh failed: {}",
            device.name,
            String::from_utf8_lossy(&out.stderr).trim()
        ));
    }
    Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

/// sha256 of a local file, as the lowercase hex `sha256sum` prints — the same form the device computes,
/// so the two are comparable without either side reformatting.
pub fn local_sha(path: &std::path::Path) -> Result<String, String> {
    let out = Command::new("sha256sum")
        .arg(path)
        .output()
        .map_err(|e| format!("cannot run sha256sum: {e}"))?;
    if !out.status.success() {
        return Err(format!("sha256sum failed for {}", path.display()));
    }
    String::from_utf8_lossy(&out.stdout)
        .split_whitespace()
        .next()
        .map(str::to_string)
        .ok_or_else(|| "sha256sum printed nothing".to_string())
}

/// Copy the artifact up as a `.partial`, then VERIFY IT ON THE DEVICE before it is given its real name.
///
/// The `.partial` suffix is what makes a truncated transfer harmless: an interrupted scp leaves a file
/// that nothing can ever resolve to, because only a verified file is renamed into place.
pub fn stage(device: &Device, local: &std::path::Path, name: &str, sha: &str) -> Result<(), String> {
    ssh(device, &format!("mkdir -p $HOME/{REMOTE_ROOT}/bin"))?;
    let dest = format!("{}:{REMOTE_ROOT}/bin/{name}-{sha}.partial", device.ssh);
    let st = Command::new("scp")
        .args(["-o", "BatchMode=yes", "-o", "ConnectTimeout=8", "-q"])
        .arg(local)
        .arg(&dest)
        .status()
        .map_err(|e| format!("cannot run scp: {e}"))?;
    if !st.success() {
        return Err(format!("{} — scp failed", device.name));
    }
    // Verified where it landed, never locally: a local check proves the bytes we made, not the ones
    // that arrived. Only then does it get the name the symlink will point at.
    let check = format!(
        "cd $HOME/{REMOTE_ROOT}/bin && \
         got=$(sha256sum {name}-{sha}.partial | cut -d' ' -f1) && \
         if [ \"$got\" != \"{sha}\" ]; then rm -f {name}-{sha}.partial; echo \"MISMATCH $got\"; exit 1; fi && \
         chmod +x {name}-{sha}.partial && mv {name}-{sha}.partial {name}-{sha} && echo OK"
    );
    let out = ssh(device, &check)?;
    if !out.ends_with("OK") {
        return Err(format!("{} — checksum mismatch on arrival: {out}", device.name));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_a_device_with_a_deploy() {
        let st = parse_state("cur=aaa111\nprev=bbb222\narch=x86_64");
        assert_eq!(st.current_sha.as_deref(), Some("aaa111"));
        assert_eq!(st.previous_sha.as_deref(), Some("bbb222"));
        assert_eq!(st.arch.as_deref(), Some("x86_64"));
    }

    #[test]
    fn an_empty_first_field_does_not_shift_the_others() {
        // The measured regression. `ssh` trims the whole output, so a bare positional format lost the
        // leading blank line for a device with nothing deployed — and lumpy-space reported "x86_64" as
        // the binary it was running while reading as unreachable. This is that exact shape.
        let st = parse_state("cur=\nprev=\narch=x86_64");
        assert_eq!(st.current_sha, None, "nothing deployed must read as None, not as the next field");
        assert_eq!(st.previous_sha, None);
        assert_eq!(st.arch.as_deref(), Some("x86_64"), "arch survives an empty field above it");
    }

    #[test]
    fn a_trimmed_output_that_dropped_leading_blanks_still_parses() {
        // What `ssh().trim()` actually hands over when the first two values are empty.
        let st = parse_state("arch=aarch64");
        assert_eq!(st.current_sha, None);
        assert_eq!(st.arch.as_deref(), Some("aarch64"), "the one real value is still found");
    }

    #[test]
    fn the_probe_script_never_ends_in_a_pipe() {
        // The guard for the measured bug. A trailing pipe takes the exit status of `head`, so a
        // segfaulting binary reported success and rollback became unreachable. Nothing at run time can
        // observe the ABSENCE of a captured status, so the shape is asserted here instead.
        let sc = probe_script("bsc");
        assert!(sc.contains("rc=$?"), "the probe must capture the binary's own status: {sc}");
        assert!(sc.contains("echo \"rc=$rc\""), "the probe must REPORT that status: {sc}");
        let last = sc.trim_end().rsplit(';').next().unwrap_or("").trim();
        assert!(!last.contains('|'), "the last command must not be a pipe — it would mask the status: {last}");
    }

    #[test]
    fn a_nonzero_binary_is_a_failure_carrying_its_code() {
        let (ok, why) = read_probe("Segmentation fault\nrc=139");
        assert!(!ok);
        assert!(why.contains("139"), "the operator needs the code: {why}");
    }

    #[test]
    fn a_zero_binary_is_healthy() {
        let (ok, out) = read_probe("bsc 0.1.0\nrc=0");
        assert!(ok);
        assert!(out.contains("bsc 0.1.0"), "the version comes back for the operator to read");
    }

    #[test]
    fn a_missing_status_is_a_failure_never_a_pass() {
        // The direction that matters. Defaulting an unparseable probe to healthy would reinstate the
        // exact blind spot the pipeline bug created.
        let (ok, why) = read_probe("some noise with no status line");
        assert!(!ok, "an unreadable probe must not read as healthy");
        assert!(why.contains("no status"), "got: {why}");
    }

    #[test]
    fn the_probe_script_still_bounds_its_output() {
        // The pipe was there for a reason; it just has to run where it cannot swallow the verdict.
        assert!(probe_script("bsc").contains("head -3"));
    }

    #[test]
    fn unreachable_reads_as_all_unknown_never_as_empty() {
        // "I could not tell" and "it has nothing" are different answers and the caller acts on them
        // differently — an unknown arch is what renders the device as unreachable.
        let st = parse_state("");
        assert_eq!(st, crate::plan::RemoteState::default());
        assert!(st.arch.is_none());
    }
}
